    /**
     * Returns a file chooser for autonomy files
     * @param type
     * @param extension
     * @return 
     */
    public JFileChooser getFileChooser(int type, String extension)
    {
        JFileChooser fc = new QuickFileChooser(
            prefs.get(LAST_USED_FOLDER, new File(".").getAbsolutePath())
        );
        
        if ("json".equals(extension))
        {
            FileFilter filter = new FileNameExtensionFilter(I18n.t("ui.jsonFile"), "json");
            fc.setFileFilter(filter);
        }
        else if ("csv".equals(extension))
        {
            FileFilter filter = new FileNameExtensionFilter(I18n.t("ui.csvFile"), "csv");
            fc.setFileFilter(filter);
        }
        else if ("txt".equals(extension))
        {
            FileFilter filter = new FileNameExtensionFilter(I18n.t("ui.textFile"), "txt");
            fc.setFileFilter(filter);
        }
        
        return fc;        
    }
    
